"""Korean RCAEval-field reports generated by Qwen, then checked. Not a display template."""
import json

from . import glossary
from .log_facts import alarm_stage, no_duplicates
from .worker_report import _counts, parse_record

FIELDS = ('status', 'problem_location', 'observed_issue', 'evidence', 'possible_cause',
          'recommended_actions', 'confidence', 'missing_information')
LABELS = {'status': '상태', 'problem_location': '위치', 'observed_issue': '관측',
          'evidence': '근거', 'possible_cause': '가능한 원인', 'recommended_actions': '권고 조치',
          'confidence': '신뢰도', 'missing_information': '부족 정보'}
WORKER_PROMPT = '''작업자 참고 기준
보고서는 상태, 위치, 관측, 근거, 가능한 원인, 권고 조치, 신뢰도, 부족 정보 순서로 읽는다.
근거는 수신 기록을 그대로 인용한 것이다. 입력에 없는 수치, 단위, 위치, 복구 결과는 없다.
경보 수준 0은 안전 단계, 1은 경고 단계, 2는 위험 단계이다. 장치 단계이며 현장이 안전하거나 위험하다는 확정은 아니다.
경보가 있으면 가능한 원인에 현장 상태와 장치 설정·감지 경로를 둘 다 확인되지 않은 가능성으로 적는다.
표준 용어 20개 중 이번 기록에 해당하는 것만 본문에 쓴다. 해당하지 않는 용어는 확정하지 않는다.
신뢰도는 비어 있다. 안전하다, 정상 작동, 정상 범위, 조치 완료, Judge 판정은 쓰지 않는다.
자동 검사를 통과하지 못한 글은 검증되지 않은 보고서이다.'''
SYSTEM = '''RCAEval 보고서 필드를 이 순서로만 한국어 JSON 객체로 작성한다. status, problem_location, observed_issue, evidence, possible_cause, recommended_actions, confidence, missing_information. 다른 키·마크다운·설명은 쓰지 않는다.
status, problem_location, glossary_line은 입력값을 그대로 복사한다. glossary_line은 missing_information의 마지막 항목이다. evidence의 각 문자열은 입력 evidence에 있는 문장을 한 글자도 바꾸지 않고 인용한다. 입력에 없는 수치·단위·위치·복구 결과를 만들지 않는다. confidence는 null이다.
입력 terminology의 20개 표준 한국어만 쓴다. 영어 용어와 별칭은 금지한다. applicable_terms는 관측 또는 가능한 원인 본문에 쓴다. glossary_line에만 있는 용어는 이번 사건의 확정이 아니다.
''' + glossary.RULES + '''
경보 수준 0·1·2는 장치 정의의 안전·경고·위험 단계이며 현장 확정이 아니다. 경보 수준이 있으면 가능한 원인에 현장 단계 가설과 설정·경로 가설을 둘 다 이름을 밝혀 쓴다. 위험 신호의 단계 정의가 없으면 제공되지 않았다고만 쓴다. 안전하다, 정상 작동, 정상 범위, 조치 완료, Judge 판정을 쓰지 않는다.'''


def _evidence(readable, span):
    alarms = _counts(readable, 'alarm_level')
    lines = [f'구간 {len(readable)}건, 시각 {span}.']
    if alarms:
        parts = []
        for value, count in sorted(alarms.items()):
            stage = alarm_stage(value)
            parts.append(f'{value:g}={count}건' + (f'({stage} 단계)' if stage else ''))
        lines.append('경보 수준: ' + ', '.join(parts) + '.')
    for key, label in (('danger_signal', '위험 신호'), ('person_detected', '사람 감지'),
                       ('flame_detected', '불꽃 감지'), ('fire_alarm', '화재 경보')):
        counts = _counts(readable, key)
        if counts:
            text = label + ': ' + ', '.join(f'{value:g}={count}건' for value, count in sorted(counts.items()))
            if key == 'danger_signal':
                text += '. 단계 정의는 제공되지 않았다'
            lines.append(text + '.')
    for key, label in (('mq2', 'MQ2'), ('mq7', 'MQ7'), ('temperature_c', '온도'), ('humidity_pct', '습도')):
        values = [item['values'][key] for item in readable if key in item['values']]
        if values:
            lines.append(f'{label}: 최솟값 {min(values):g}, 최댓값 {max(values):g}. 단위·임계값은 미제공.')
    return lines


def packet(records):
    """Computed interval facts. The model may quote these lines and must not invent others."""
    parsed = [parse_record(record.get('text') or record.get('log_text') or '') for record in records]
    sensor = next((record.get('sensor_id') or item['sensor_id'] for record, item in zip(records, parsed)
                   if record.get('sensor_id') or item['sensor_id']), '미제공')
    readable = [item for item in parsed if item['values']]
    location = f'센서 {sensor}'
    if not readable:
        evidence = [item['raw'][:240] for item in parsed[:3]] or ['원문 없음']
        return _with_terms({'required_status': '형식 미지원', 'problem_location': location, 'evidence': evidence,
                            'require_alarm_hypotheses': False, 'has_measurement': False, 'has_alarm': False,
                            'has_temperature': False,
                            'missing_information': ['지원 필드가 없어 경보 단계와 변화 방향을 계산하지 않았다.']})
    alarms = _counts(readable, 'alarm_level')
    stages = {int(value): alarm_stage(value) for value in alarms if alarm_stage(value)}
    flickering = len(_counts(readable, 'danger_signal')) > 1 or len(_counts(readable, 'person_detected')) > 1
    if 2 in stages:
        status = '위험 단계 보고'
    elif 1 in stages:
        status = '경고 단계 보고'
    elif flickering:
        status = '흔들림'
    elif stages:
        status = f'{next(iter(stages.values()))} 단계 보고'
    else:
        status = '단계 미보고'
    stamps = [item['values']['timestamp'] for item in readable if 'timestamp' in item['values']]
    span = stamps[0] if len(set(stamps)) == 1 else (f'{min(stamps)}–{max(stamps)}' if stamps else '시각 미제공')
    missing = ['가스 센서 단위와 물리 위치는 미제공이다.', '독립적인 현장 관측, 로그·트레이스, 복구 결과는 없다.']
    if _counts(readable, 'danger_signal'):
        missing.insert(1, '위험 신호의 단계 정의는 제공되지 않았다.')
    facts = {'required_status': status, 'problem_location': location, 'evidence': _evidence(readable, span),
             'require_alarm_hypotheses': bool(alarms), 'has_measurement': True,
             'has_alarm': bool(alarms), 'has_temperature': any('temperature_c' in item['values'] for item in readable),
             'missing_information': missing}
    return _with_terms(facts)


def glossary_entries():
    entries = glossary.load()[0]['entries']
    if len(entries) != 20:
        raise ValueError('expected the 20 project glossary terms')
    return entries


def glossary_line():
    return '표준 용어: ' + ', '.join(entry['korean'] for entry in glossary_entries()) + '. 해당 근거가 없는 용어는 확정하지 않는다.'


def applicable_terms(facts):
    terms = ['판단 근거', '신뢰도 점수']
    if facts.get('has_measurement'):
        terms.append('센서 측정값')
    if facts.get('has_alarm'):
        terms.append('경보 이벤트')
    if facts.get('has_temperature'):
        terms.append('온도 센서')
    if facts.get('has_measurement') or facts.get('has_alarm'):
        terms.append('임계값')
    if facts.get('require_alarm_hypotheses') or facts.get('required_status') == '이상 징후':
        terms.append('근본 원인')
    if facts.get('required_status') == '이상 징후':
        terms.append('이상 징후')
    return terms


def _with_terms(facts):
    facts = dict(facts)
    facts['glossary_line'] = glossary_line()
    facts['applicable_terms'] = applicable_terms(facts)
    facts['missing_information'] = [*facts['missing_information'], facts['glossary_line']]
    return facts


def messages_for(facts):
    glossary_rows = [{'en': entry['english'], 'ko': entry['korean'], 'note': entry['translation_notes']}
                     for entry in glossary_entries()]
    user = {'required_status': facts['required_status'], 'problem_location': facts['problem_location'],
            'evidence': facts['evidence'], 'require_alarm_hypotheses': facts['require_alarm_hypotheses'],
            'applicable_terms': facts['applicable_terms'], 'glossary_line': facts['glossary_line'],
            'missing_information': facts['missing_information'], 'terminology': glossary_rows,
            'confidence': None}
    return [{'role': 'system', 'content': SYSTEM},
            {'role': 'user', 'content': json.dumps(user, ensure_ascii=False)}]


def render(report):
    if list(report) != list(FIELDS):
        raise ValueError('report field order does not match RCAEval')
    lines = []
    for key in FIELDS:
        value = report[key]
        title = LABELS[key]
        if value is None:
            lines.append(f'{title}: 미제공')
        elif isinstance(value, list):
            lines.append(title + ':')
            lines.extend(f'- {item}' for item in value)
        else:
            lines.append(f'{title}: {value}')
    return '\n'.join(lines)


def training_target(facts):
    """Synthetic Korean target for SFT. Live reports must come from the model, not this function."""
    status = facts['required_status']
    quoted = facts['evidence'][:3]
    used = ' '.join(facts['applicable_terms'])
    if status == '형식 미지원':
        issue = f'이 구간은 기존 파서가 수치로 읽지 못하는 원문이다. 적용 용어는 {used}이다. 신뢰도 점수는 제공되지 않았다.'
        cause = None
        action = '원본 형식과 센서 식별자를 대조한다. 수리 완료로 쓰지 않는다.'
    elif facts['require_alarm_hypotheses']:
        issue = (f'{status}. 판단 근거는 입력된 센서 측정값 인용이다. 경보 이벤트는 현장 확정이 아니다. '
                 f'임계값은 미제공이다. 신뢰도 점수는 제공되지 않았다. 적용 용어는 {used}이다.')
        cause = '현장 단계 가설과 설정·경로 가설이 모두 가능하다. 둘 다 미검증이며 근본 원인으로 단정하지 않는다.'
        action = '보고된 경보 단계와 같은 시각의 현장을 대조하고, 불일치하면 경보 조건과 감지 경로를 확인한다.'
    else:
        issue = f'{status}. 인용된 판단 근거 밖에서 단계를 계산하지 않았다. 적용 용어는 {used}이다. 신뢰도 점수는 제공되지 않았다.'
        cause = None
        action = '원본 형식과 센서 식별자를 대조한다.'
    if facts.get('has_temperature') and '온도 센서' not in issue:
        issue += ' 온도 센서 수치는 인용된 범위만 쓴다.'
    report = {'status': status, 'problem_location': facts['problem_location'], 'observed_issue': issue,
              'evidence': quoted, 'possible_cause': cause, 'recommended_actions': [action],
              'confidence': None, 'missing_information': list(facts['missing_information'])}
    validate(json.dumps(report, ensure_ascii=False), facts)
    return report


def _first_object(raw):
    """The model's first JSON object. Trailing repetition is not part of the report."""
    text = raw.strip()
    if text.startswith('```'):
        text = text.split('\n', 1)[1].rsplit('```', 1)[0].strip()
    start = text.find('{')
    if start < 0:
        return text
    depth = 0
    in_string = False
    escape = False
    for index, char in enumerate(text[start:], start):
        if in_string:
            if escape:
                escape = False
            elif char == '\\':
                escape = True
            elif char == '"':
                in_string = False
            continue
        if char == '"':
            in_string = True
        elif char == '{':
            depth += 1
        elif char == '}':
            depth -= 1
            if depth == 0:
                return text[start:index + 1]
    return text


def validate(raw, facts):
    report = json.loads(_first_object(raw), object_pairs_hook=no_duplicates)
    if not isinstance(report, dict) or list(report) != list(FIELDS):
        raise ValueError('expected RCAEval fields in order')
    if report['status'] != facts['required_status'] or report['problem_location'] != facts['problem_location']:
        raise ValueError('status or location was not preserved')
    if report['confidence'] is not None:
        raise ValueError('confidence must stay null')
    for key, kind in (('observed_issue', str), ('possible_cause', (str, type(None)))):
        if not isinstance(report[key], kind) or (kind is str and not report[key].strip()):
            raise ValueError(f'invalid {key}')
    for key in ('evidence', 'recommended_actions', 'missing_information'):
        if not isinstance(report[key], list) or not report[key] or any(not isinstance(item, str) or not item.strip() for item in report[key]):
            raise ValueError(f'invalid {key}')
    if any(item not in facts['evidence'] for item in report['evidence']):
        raise ValueError('evidence is not an exact quote from the supplied lines')
    rendered = render(report)
    residual = rendered
    for item in report['evidence']:
        residual = residual.replace(item, '')
    residual = residual.replace(report['problem_location'], '')
    if any(character.isdigit() for character in residual):
        raise ValueError('unbound numeric assertion')
    if 'Anomaly' in rendered or '어노말리' in rendered or '안전하다' in rendered or '정상 작동' in rendered:
        raise ValueError('unsupported status or safety claim')
    if '단계 의미가 미제공' in rendered:
        raise ValueError('do not withhold a provided alarm-stage meaning')
    if facts['require_alarm_hypotheses']:
        possibilities = f"{report['observed_issue']}\n{report['possible_cause'] or ''}"
        if '현장' not in possibilities or not any(word in possibilities for word in ('설정', '경로')):
            raise ValueError('alarm interval must raise both site and device-path possibilities')
    if facts['glossary_line'] not in report['missing_information']:
        raise ValueError('the 20 standard terms were omitted')
    prose = '\n'.join(part for part in (report['observed_issue'], report['possible_cause'] or '',
                                        ' '.join(report['recommended_actions'])) if part)
    missing_terms = [term for term in facts['applicable_terms'] if term not in prose]
    if missing_terms:
        raise ValueError('applicable glossary terms missing: ' + ', '.join(missing_terms))
    terminology = glossary.validate_report(rendered, {'entries': [
        {'english': entry['english'], 'korean': entry['korean'], 'review_required': False}
        for entry in glossary_entries()]})
    if terminology['errors']:
        raise ValueError('technical terminology validation failed: ' + json.dumps(terminology['errors'], ensure_ascii=False))
    return report, rendered, terminology


def generate(backend, records, max_new_tokens=1024):
    """Return the model report even when checks fail, with an explicit unverified flag."""
    facts = packet(records)
    messages = messages_for(facts)
    history = []
    last = None
    complete = None
    for attempt in range(2):
        result = backend.generate(messages, max_new_tokens, repetition_penalty=1.12, logits_to_keep=0)
        last = result
        history.append({'attempt': attempt + 1, 'output_tokens': result.get('output_tokens'),
                        'finish_reason': result.get('finish_reason')})
        try:
            report, rendered, terminology = validate(result['raw_text'], facts)
            return {'text': rendered, 'passed': True, 'error': None, 'report': report,
                    'facts': facts, 'terminology': terminology, 'history': history, 'raw': result['raw_text']}
        except (ValueError, TypeError, KeyError, json.JSONDecodeError) as exc:
            history[-1]['validation_error'] = str(exc)
            if _first_object(result['raw_text']).endswith('}'):
                complete = (result, str(exc))
            if attempt:
                break
            messages = [*messages, {'role': 'assistant', 'content': _first_object(result['raw_text'])},
                        {'role': 'user', 'content': '검사 오류: ' + str(exc)
                         + '. 직전 JSON에서 빠진 항목만 고치고, 같은 문장을 반복하지 마라.'}]
    chosen, error = complete if complete else (last or {}, history[-1].get('validation_error', 'validation failed'))
    raw = chosen.get('raw_text') or ''
    return {'text': raw.strip() or '모델 출력이 비어 있다.', 'passed': False,
            'error': error,
            'report': None, 'facts': facts, 'terminology': None, 'history': history, 'raw': raw}
